function pilot(c,g){const q=g.rooftop201,t=q.t;let i=4,x=q.pilot.x,y=q.pilot.y;if(q.phase==='surprise')i=5;if(q.phase==='rush')i=q.knocked?6:5;if(['knockout','board','startup','lift','depart','choice','complete'].includes(q.phase)){const u=q.phase==='knockout'?N.clamp(t/.45,0,1):1;i=u<.8?6:7;x+=u*54;}c.save();c.fillStyle='#091b2944';c.beginPath();c.ellipse(x,y+2,i===7?65:21,4,0,0,7);c.fill();frame(c,i,x,y,180/414);c.restore();if(['roofIn','approach'].includes(q.phase)){c.save();c.strokeStyle='#e6e4e466';c.lineWidth=1.3;for(let j=0;j<3;j++){const a=((q.total*.5+j*.31)%1),px=x-27-a*11,py=y-145-a*35;c.globalAlpha=(1-a)*.5;c.beginPath();c.moveTo(px,py);c.quadraticCurveTo(px+8,py-9,px-1,py-18);c.stroke();}c.restore();}}
function helicopter(c,g,reduced){const q=g.rooftop201,h=q.heli,k=536/408,index=['board','roofIn','approach','surprise','rush','knockout'].includes(q.phase)?0:['lift','depart'].includes(q.phase)?2:1;c.save();const height=Math.max(0,475-h.y);c.globalAlpha=Math.max(.08,.3-height/1000);c.fillStyle='#06101c';c.beginPath();c.ellipse(h.x,481,190-height*.18,13-height*.008,0,0,7);c.fill();c.globalAlpha=1;frame(c,index,h.x,h.y,k);
const power=q.rotor||0,rx=h.x-8,ry=h.y-204;if(power>.58||reduced&&power>0){c.fillStyle='#a7b5c533';c.strokeStyle='#c7d2df55';c.lineWidth=2;c.beginPath();c.ellipse(rx,ry,257,8,0,0,Math.PI*2);c.fill();c.stroke();}else{const phase=reduced?0:q.total*(.3+power*25);c.strokeStyle='#1b2736';c.lineWidth=4;for(let j=0;j<2;j++){const a=phase+j*Math.PI/2;c.beginPath();c.moveTo(rx-Math.cos(a)*250,ry-Math.sin(a)*8);c.lineTo(rx+Math.cos(a)*250,ry+Math.sin(a)*8);c.stroke();}}
const tx=h.x-247,ty=h.y-104;c.strokeStyle='#96a5b366';c.lineWidth=2;c.beginPath();c.arc(tx,ty,16,0,Math.PI*2);c.stroke();if(power<.6){const ph=reduced?0:q.total*(1+power*40);for(let j=0;j<3;j++){const a=ph+j*Math.PI*2/3;c.beginPath();c.moveTo(tx,ty);c.lineTo(tx+Math.cos(a)*15,ty+Math.sin(a)*15);c.stroke();}}c.restore();}
function hero(c,g){const q=g.rooftop201,p=g.player;if(q.inside)return;const k=N.Forest125.scale(p);c.save();c.translate(p.x,p.y);c.scale(k,k);S.draw(c,p,g.time,k);c.restore();if(g.gunner125&&!['board','startup','lift','depart'].includes(q.phase))(()=>{const d=g.gunner125;c.save();c.translate(d.x,d.y);c.scale(1.46515635,1.46515635);S.draw(c,d,g.time);c.restore();})();}
function render(c,g,reduced=false){const q=g.rooftop201;c.fillStyle='#071221';c.fillRect(0,0,960,540);root.UrbanEnvironmentView156.background(c,g,()=>background(c,g));if(q.phase!=='board'||q.t/R.config.board<.78)helicopter(c,g,reduced);pilot(c,g);hero(c,g);if(q.phase==='board'&&q.t/R.config.board>=.78)helicopter(c,g,reduced);root.UrbanEnvironmentView156.foreground(c,g,reduced);c.fillStyle='#07101eea';c.fillRect(0,0,960,68);c.fillRect(0,510,960,30);c.fillStyle='#e7dfbd';c.font='bold 15px monospace';c.fillText('UNION NATIONAL BANK · ROOFTOP',24,30);c.font='12px monospace';c.fillStyle='#b8d7d8';c.fillText(g.player.name+' · '+(q.phase==='depart'?'A NEW LEAD AWAITS':q.phase==='lift'?'HELICOPTER SECURED':'THE PILOT NEVER SAW IT COMING'),24,53);c.fillText('FINANCIAL DISTRICT · THE ESCAPE',24,530);if(g.transitionAlpha>0){c.fillStyle='rgba(0,0,0,'+g.transitionAlpha+')';c.fillRect(0,0,960,540);}}
let mix;function audioUpdate(audio,g,on){const q=g.rooftop201,power=q?.rotor||0,enabled=!!(on&&q&&!R.menu(g));if(!audio)return;if(!mix&&enabled&&power>0){const gain=audio.createGain();gain.gain.value=0;gain.connect(audio.destination);const osc=audio.createOscillator(),lfo=audio.createOscillator(),pulse=audio.createGain();osc.type='triangle';osc.frequency.value=72;lfo.frequency.value=18;pulse.gain.value=.22;lfo.connect(pulse.gain);osc.connect(pulse);pulse.connect(gain);osc.start();lfo.start();mix={gain,osc,lfo};}if(mix){mix.gain.gain.setTargetAtTime(enabled?Math.min(.075,power*.075):0,audio.currentTime,.2);mix.osc.frequency.setTargetAtTime(48+power*40,audio.currentTime,.3);mix.lfo.frequency.setTargetAtTime(8+power*13,audio.currentTime,.3);}}
